// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    // fuzzed params: amount to deposit (must fit in contract balance) and a uint8 switch
    // amount is fuzzed so fuzzer can find a case where a positive balance exists
    function testFuzz_property(uint256 amount, uint8 chooser) public {
        // Keep amount in a sensible wide range but exclude extremely large amounts
        amount = bound(amount, 0, 1 ether);
        // we only care when amount > 0 because withdraw of zero is uninteresting
        vm.assume(amount > 0);

        // deploy a recording helper that will record what it receives when c.call is made
        Recorder r = new Recorder();

        // fund the user who will deposit
        address depositor = address(0xBEEF);
        vm.deal(depositor, amount);
        vm.startPrank(depositor);
        // deposit into c
        c.addToBalance{value: amount}();
        vm.stopPrank();

        // sanity: internal balance matches
        uint256 beforeInternal = c.getBalance(depositor);
        assert(beforeInternal == amount);

        // Now have the depositor call withdrawBalance but as the recorder contract by using chooser
        // We want c to call msg.sender (the caller) — so we must make the caller be the recorder
        // To allow the depositor's stored balance to be associated with the recorder's address,
        // we instead deposit from the recorder. So redo: deposit from recorder.
        // Reset and do the scenario correctly: redeploy clean C and recorder, and perform deposit from recorder.
        // (Because earlier deposit was from depositor, which doesn't match recorder.)
        // For cleanliness, redeploy c and set up fresh state.
        c = new Reentrance();
        r = new Recorder();

        // fund recorder and have it deposit
        vm.deal(address(r), amount);
        r.depositTo(address(c));

        // check internal mapping recorded by c for recorder address
        uint256 recInternal = c.getBalance(address(r));
        assert(recInternal == amount);

        // Now call withdrawBalance from recorder so c will call back to recorder and recorder will record msg.value
        // The behavior difference: correct C will call recorder with value == amount; mutant calls with value == 0
        r.withdrawFrom(address(c));

        // After withdraw, the internal mapping for recorder must be zero (both reference and mutant zero it locally)
        uint256 afterInternal = c.getBalance(address(r));
        assert(afterInternal == 0);

        // The distinguishing observable: what the recorder observed as msg.value in the external call from c.
        // For the correct contract this must equal the previously-stored amount; the mutant sending 0 breaks it.
        uint256 recordedValue = r.lastValue();

        // Single universal assertion: for ALL admissible inputs (amount>0), the reference C forwards the withdrawn
        // amount to msg.sender, so recorder must have observed msg.value == amount. The mutant that sends 0 will
        // cause recordedValue == 0 for some inputs and thus fail this assertion.
        assertTrue(recordedValue == amount);
    }
}

// Minimal recording helper that can deposit to C and then call withdrawBalance so C's external call targets this contract.
contract Recorder {
    uint256 public lastValue;

    // deposit into C by calling addToBalance payable
    function depositTo(address cAddr) external payable {
        // forward all balance this contract holds
        Reentrance(cAddr).addToBalance{value: address(this).balance}();
    }

    // trigger withdrawBalance on C while msg.sender is this contract
    function withdrawFrom(address cAddr) external {
        Reentrance(cAddr).withdrawBalance();
    }

    // This fallback will be invoked by C's low-level call; record msg.value
    fallback() external payable {
        lastValue = msg.value;
    }
    receive() external payable {
        lastValue = msg.value;
    }
}
